    def get_any(d, keys, default=None):
        for k in keys:
            if isinstance(d, dict) and k in d:
                return d.get(k)
        return default

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return int(a), int(b)
        if isinstance(x, dict):
            for ax, ay in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if ax in x and ay in x and isinstance(x.get(ax), (int, float)) and isinstance(x.get(ay), (int, float)):
                    return int(x.get(ax)), int(x.get(ay))
        return None

    def extract_positions(v):
        out = []
        if v is None:
            return out
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                p = as_pos(v)
                if p is not None:
                    out.append(p)
            else:
                for vv in v.values():
                    out.extend(extract_positions(vv))
        elif isinstance(v, (list, tuple)):
            for item in v:
                p = as_pos(item)
                if p is not None:
                    out.append(p)
                else:
                    out.extend(extract_positions(item))
        return out

