                s -= max(0, 14 - 3 * dmin)

            if friends:
                dmin = min(manhattan((nx, ny), p) for p in friends)
                s -= max(0, 3 - dmin)

            if owned:
                owner = owned.get((nx, ny))
                if my_id is not None and owner == my_id:
                    s += 1
                elif owner is not None and my_id is not None and owner != my_id:
                    s += 4
                else:
                    s += 2

            if width is not None and height is not None:
                cx, cy = width // 2, height // 2
                s -= (abs(nx - cx) + abs(ny - cy)) * 0.05

            if dx == 0 and dy == 0:
